                        rr=L-1-k
                        cc=c+k; cc2=c-k
                        if rr>=0 and 0<=cc<W and 0<=cc2<W:
                            O[rr][cc]=4; O[rr][cc2]=4
                        else: break
                        k+=1
                else:
                    if r+1<H: O[r+1][c]=4
    return O
